"""Migration of Meridian CRM 4.2 order validation rules ORD-001 through ORD-005."""

from decimal import Decimal, InvalidOperation
from typing import Any


_BLOCK = "BLOCK"


def _value(row: dict | None, column: str) -> Any:
    """Return a field value, with missing fields behaving as empty strings."""
    if row is None:
        return ""
    return row.get(column, "")


def _number(value: Any) -> Decimal:
    """Apply legacy numeric coercion for empty/missing values."""
    if value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: Any,
    output_column: str,
) -> Any:
    """Implement legacy LOOKUP, including live-row-only behavior."""
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)
    return ""


def _error(code: str, message: str) -> dict:
    return {"code": code, "message": message, "severity": _BLOCK}


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or line using the legacy rule-file order."""
    errors: list[dict] = []

    if table == "ORD_HEADER":
        # ORD-001: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            disc_pct = _number(_value(record, "DISC_PCT"))
            if not (disc_pct >= Decimal("0") and disc_pct <= Decimal("100")):
                errors.append(_error("E5001", "Discount out of range"))

        # ORD-002: UPDATE
        if event == "UPDATE":
            disc_pct = _number(_value(record, "DISC_PCT"))
            role_id = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _value(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if disc_pct > Decimal("20") and role_id != "MGR" and role_id != "ADMIN":
                errors.append(
                    _error(
                        "E5002",
                        "Discount over 20 percent requires manager role",
                    )
                )

        # ORD-003: UPDATE
        if event == "UPDATE":
            old_status = _value(old, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                errors.append(
                    _error("E5003", "Invoiced order can only be cancelled")
                )

    elif table == "ORD_LINE":
        # ORD-004: INSERT, UPDATE
        if event in ("INSERT", "UPDATE"):
            if not (_number(_value(record, "QTY")) > Decimal("0")):
                errors.append(_error("E5004", "Quantity must be positive"))

        # ORD-005: INSERT
        if event == "INSERT":
            active_flag = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _value(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flag != "Y":
                errors.append(_error("E5005", "Product not active"))

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == _BLOCK for error in errors)
